steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
H.shift("U_FLASH_GITZ_A", 0, 3)
return H.setup(1, {"cp": {"2": 0}})

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
PhaseManager.transition_to_phase(8)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.frame(26, 34, 1.2)

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.shoot("U_HELLBLASTER_SQUAD_A", "U_FLASH_GITZ_A")

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.decline_until_window("unit_has_shot") >= 0

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return "U_FLASH_GITZ_A" in H.phase().get_pending_stratagem_window().get("ctx", {}).get("hit_unit_ids", [])

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
var f = H.flag("U_FLASH_GITZ_A", "sm11e_suppressed")
return typeof(f) == TYPE_DICTIONARY and int(f.get("player", 0)) == 1

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return bool(H.mods("U_FLASH_GITZ_A", "U_HELLBLASTER_SQUAD_A", false).get("hit_minus", false))

var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3b_scen.gd")
return H.log_count("Used DOMINATION FIRE")
